mapper.select:
SELECT t1.INFO_TYPE AS infoType , t1.SHRN_ISCD AS shrnIscd , t1.STND_ISCD AS stndIscd , t1.KOR_NAME AS korName , t1.ATM_CLS_CODE AS atmClsCode , t1.ACPR AS acpr , t1.MMSC_CLS_CODE AS mmscClsCode , t1.UNAS_SHRN_ISCD AS unasShrnIscd , t1.UNAS_KOR_NAME AS unasKorName , CASE t1.ATM_CLS_CODE WHEN '1' THEN 'ATM' WHEN '2' THEN 'ITM' WHEN '3' THEN 'OTM' ELSE t1.ATM_CLS_CODE END AS atmClsName , CASE t1.MMSC_CLS_CODE WHEN '0' THEN '연결선물' WHEN '1' THEN '최근월물' WHEN '2' THEN '차근월물' WHEN '3' THEN '차차근월물' WHEN '4' THEN '차차차근월물' ELSE t1.MMSC_CLS_CODE END AS mmscClsName FROM FO_IDX_CODE t1 WHERE 1 = 1
AND t1.INFO_TYPE = #{infoType}
ORDER BY t1.INFO_TYPE ASC, t1.STND_ISCD ASC

SELECT COUNT(1)
  FROM FO_IDX_CODE
 WHERE INFO_TYPE = #{infoType}
   AND STND_ISCD = #{stndIscd}

mapper.update:
UPDATE FO_IDX_CODE
   SET SHRN_ISCD      = #{shrnIscd, jdbcType=VARCHAR},
       KOR_NAME       = #{korName, jdbcType=VARCHAR},
       ATM_CLS_CODE   = #{atmClsCode, jdbcType=VARCHAR},
       ACPR           = #{acpr, jdbcType=NUMERIC},
       MMSC_CLS_CODE  = #{mmscClsCode, jdbcType=VARCHAR},
       UNAS_SHRN_ISCD = #{unasShrnIscd, jdbcType=VARCHAR},
       UNAS_KOR_NAME  = #{unasKorName, jdbcType=VARCHAR}
 WHERE INFO_TYPE      = #{infoType}
   AND STND_ISCD      = #{stndIscd}

mapper.delete:
DELETE FROM FO_IDX_CODE
 WHERE INFO_TYPE = #{infoType}
   AND STND_ISCD = #{stndIscd}
